from pathlib import Path
import os,json,time,subprocess,hashlib,shutil,sys,threading

ROOT=Path(__file__).resolve().parent
WS=ROOT.parent
R2=WS/'r3_restore/r2/buffer_growth'
BIN=WS/'buffer_growth/work_r2/replay/Replay.dll'
HOST=WS/'dotnet_host/dotnet'
INPUT=WS/'v4_resume/inputs'
EXPECTED='79b61fb0565957ed792a67c8c0de08e18c5a5e8b2b892ccb1c320f9ad9b5e653'
CEILING=72.21320348415222
FLOOR=842853657.6189626

def put(path,obj):
    temp=path.with_suffix(path.suffix+'.tmp')
    temp.write_text(json.dumps(obj,indent=2));temp.replace(path)

def init():
    assert hashlib.sha256(BIN.read_bytes()).hexdigest()==EXPECTED
    base=json.loads((R2/'BUFFER_EUR_BTC_V2_CANDIDATE.json').read_text())[0]
    profiles=[]
    for tag,initial,window in [('I090_W180',.9,180),('I100_W060',1,60),('I090_W060',.9,60)]:
        p=dict(base,Id='R3_'+tag,EurInitial=initial,EurWindow=window)
        assert all(p[k]==v for k,v in base.items() if k not in ['Id','EurInitial','EurWindow'])
        profiles.append(p);put(ROOT/(p['Id']+'.json'),[p])
    put(ROOT/'SCREEN_PROFILES.json',profiles)
    for name in ['fresh_xau_tape.json','fresh_eur_tape.json']:
        dest=ROOT/name
        if not dest.exists():dest.symlink_to(WS/'buffer_growth'/name)
    for name in ['FROZEN_BUFFER_LOCK.json','audit_growth.py','aggregate_growth.py']:
        shutil.copy2(R2/name,ROOT/name)
    put(ROOT/'PLAN.json',{'created_utc':time.time(),'scope':'REPLAY only; BUFFER V1, XAU, BTC32 and LIVE unchanged','r2_archive':'libfile_583f19ae940c8191a192731d6e8c7274','binary_sha256':EXPECTED,'profiles':profiles,'screens':[{'way':'B','cost':c} for c in [2,1]],'selection':'Two distinct audited screening leaders: highest normal B balance and lowest worst DD across B1/B2. Prefer candidates within frozen DD ceiling and B2 floor; no silent relaxation. Include R2 as an existing comparator. If leaders both R2, validate best R3 challenger by normal balance to learn whether screen rejection holds on A. Full six required for any final claim.','acceptance':{'dd_ceiling':CEILING,'cost2_floor':FLOOR,'normal_A_floor':988747417.2738367,'normal_B_floor':938466200.2239354,'own_EUR_BTC_all6_pnl_improve':True},'independent_OOS':False,'real_ticks':False,'spread_stressed':False})
    return profiles

def replay(profiles,folder,cost,way,on_loaded=None):
    out=ROOT/folder;out.mkdir(exist_ok=True)
    config=out/'profiles.json';put(config,profiles)
    completed=[];todo=[]
    for p in profiles:
        target=out/f"{p['Id']}_{way}_cost{cost}.json.gz"
        # Only a completed metrics row plus nonempty raw report can be reused.
        metrics=out/'RUN.json.metrics.json'
        rows=json.loads(metrics.read_text()) if metrics.exists() else []
        if target.exists() and any(x['Profile']['Id']==p['Id'] for x in rows):completed.append(p)
        else:todo.append(p)
    if not todo:
        print('REUSE',folder,flush=True)
        if on_loaded:on_loaded.set()
        return
    put(config,todo)
    env=os.environ.copy();env.update(BTC_INPUT=str(INPUT/'BTCUSD_M1.csv'),BTC_SIGNAL_CACHE=str(WS/'v4_resume/baseline/results/FROZEN_7D130_A.json.btc_signals.json'),RESEARCH_CONFIGS=str(config),RESEARCH_PATH=way,RESEARCH_COST=str(cost),DOTNET_GCHeapHardLimit='0xC0000000',DOTNET_gcServer='1',DOTNET_GCHeapCount='4')
    cmd=[str(HOST),str(BIN),str(INPUT/'xau_2012_2026.csv'),str(INPUT/'eur_2012_2026.csv'),str(out/'RUN.json'),'full','2019','2026']
    info={'started_utc':time.time(),'cmd':cmd,'cost':cost,'way':way,'profiles':todo,'binary_sha256':EXPECTED,'environment':{k:v for k,v in env.items() if k.startswith(('BTC_','RESEARCH_','DOTNET_'))}}
    with (out/'replay.log').open('w') as log:
        p=subprocess.Popen(cmd,env=env,stdout=log,stderr=log);info['pid']=p.pid;put(out/'JOB.json',info)
        print('START',folder,p.pid,flush=True)
        last=''
        while p.poll() is None:
            time.sleep(15)
            lines=(out/'replay.log').read_text(errors='replace').splitlines()
            if lines and lines[-1]!=last:
                last=lines[-1];print(folder,last[:550],flush=True)
            if on_loaded and any(x.startswith('TAPES ') for x in lines):on_loaded.set()
        info.update(returncode=p.returncode,finished_utc=time.time());put(out/'JOB.json',info)
    if on_loaded:on_loaded.set()
    print('END',folder,p.returncode,flush=True)
    if p.returncode:raise RuntimeError(f'{folder}: replay failed {p.returncode}')

def audit():
    log=ROOT/'audit.log'
    with log.open('w') as f:subprocess.run([sys.executable,str(ROOT/'audit_growth.py')],stdout=f,stderr=subprocess.STDOUT,check=True)
    rows=json.loads((ROOT/'RESULTS.json').read_text())
    if not all(x['pass'] for x in rows):raise RuntimeError('Full audit failed; inspect RESULTS.json')
    return rows

def leaders(rows,profiles):
    old=json.loads((R2/'RESULTS.json').read_text())
    old=[x for x in old if x['id']=='BUFFER_EUR_BTC_V2_CANDIDATE' and x['way']=='B' and x['cost'] in [1,2]]
    scores=[]
    for pid in [p['Id'] for p in profiles]+['BUFFER_EUR_BTC_V2_CANDIDATE']:
        pair=[x for x in rows+old if x['id']==pid and x['way']=='B' and x['cost'] in [1,2]]
        assert len(pair)==2,(pid,len(pair))
        normal=next(x for x in pair if x['cost']==1);stress=next(x for x in pair if x['cost']==2)
        scores.append({'id':pid,'normal_balance':normal['balance'],'stress_balance':stress['balance'],'worst_dd':max(x['dd'] for x in pair),'audited':all(x['pass'] for x in pair),'within_portfolio_screen_limits':max(x['dd'] for x in pair)<=CEILING and stress['balance']>=FLOOR})
    eligible=[x for x in scores if x['audited'] and x['within_portfolio_screen_limits']]
    top=max(eligible,key=lambda x:x['normal_balance']);low=min(eligible,key=lambda x:x['worst_dd'])
    selected=list(dict.fromkeys(x['id'] for x in [top,low] if x['id'].startswith('R3_')))
    if not selected:selected=[max((x for x in scores if x['id'].startswith('R3_')),key=lambda x:x['normal_balance'])['id']]
    put(ROOT/'SELECTION.json',{'scores':scores,'highest_balance_screen':top,'lowest_dd_screen':low,'selected_for_full6':selected,'not_final_until_full6':True})
    return [p for p in profiles if p['Id'] in selected]

def main():
    profiles=init();put(ROOT/'STATUS.json',{'stage':'screening','started_utc':time.time(),'complete':False})
    # Stagger input loading; cap each managed heap at 3 GiB on 8 GiB host.
    loaded=threading.Event();errors=[]
    def stress():
        try:replay(profiles,'SCREEN_B_C2',2,'B',loaded)
        except BaseException as e:errors.append(repr(e));loaded.set()
    worker=threading.Thread(target=stress);worker.start()
    while not loaded.wait(15):print('WAIT input loading B2',flush=True)
    if errors:raise RuntimeError(errors)
    replay(profiles,'SCREEN_B_C1',1,'B');worker.join()
    if errors:raise RuntimeError(errors)
    rows=audit();selected=leaders(rows,profiles)
    put(ROOT/'STATUS.json',{'stage':'full_six_validation','selected':[p['Id'] for p in selected],'screen_runs_complete':6,'complete':False})
    for cost,way in [(2,'A'),(1,'A'),(1.5,'A'),(1.5,'B')]:replay(selected,f'FINAL_{way}_C{cost}',cost,way)
    audit()
    subprocess.run([sys.executable,str(ROOT/'aggregate_growth.py')],check=True)
    put(ROOT/'STATUS.json',{'stage':'all_replays_and_audits_complete','complete':True,'finished_utc':time.time(),'selected':[p['Id'] for p in selected]})

if __name__=='__main__':
    try:main()
    except BaseException as e:
        put(ROOT/'STATUS.json',{'stage':'error','error':repr(e),'complete':False,'at_utc':time.time()});raise

