from pathlib import Path
import json,gzip,hashlib,csv,collections,zipfile,time,sys

R=Path(__file__).resolve().parent
WS=R.parent
BASE=WS/'r3_restore/r2/buffer_growth'
def read(p):return json.loads(p.read_text())
def write(p,v):p.write_text(json.dumps(v,indent=2))
def csvout(name,rows):
    if not rows:return
    with (R/name).open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)

def main():
    status=read(R/'STATUS.json');assert status.get('complete'),status
    rows=read(R/'RESULTS.json');assert rows and all(x['pass'] for x in rows)
    r2=[x for x in read(BASE/'RESULTS.json') if x['id']=='BUFFER_EUR_BTC_V2_CANDIDATE']
    assert len(r2)==6
    prior=read(BASE/'COMBINED_ACCEPTANCE.json')
    frozen={(x['way'],x['cost'],x['symbol']):x['frozen_pnl'] for x in prior['pnl_comparison']}
    lock=read(R/'FROZEN_BUFFER_LOCK.json')
    binary=WS/'buffer_growth/work_r2/replay/Replay.dll'
    binary_sha=hashlib.sha256(binary.read_bytes()).hexdigest()
    assert binary_sha=='79b61fb0565957ed792a67c8c0de08e18c5a5e8b2b892ccb1c320f9ad9b5e653'
    frozen_r2=read(R/'FROZEN_R2_REFERENCE.json') if (R/'FROZEN_R2_REFERENCE.json').exists() else None
    if frozen_r2:
        assert frozen_r2['immutable'] and frozen_r2['binary_sha256']==binary_sha
        for name,digest in frozen_r2['benchmark_member_sha256'].items():
            assert hashlib.sha256((BASE/name).read_bytes()).hexdigest()==digest,('Frozen R2 benchmark changed',name)
        assert read(BASE/'BUFFER_EUR_BTC_V2_CANDIDATE.json')==frozen_r2['config']
    for rel,sha in lock['source_sha256'].items():
        if '/source/xau/' in rel:
            p=WS/'buffer_growth/work_r2'/rel.split('/',1)[1]
            assert hashlib.sha256(p.read_bytes()).hexdigest()==sha,(rel,'XAU changed')
    provenance=[]
    for x in rows:
        p=R/x['file'];assert hashlib.file_digest(p.open('rb'),'sha256').hexdigest()==x['sha256']
        j=read(p.parent/'JOB.json');assert j.get('returncode')==0 and j['binary_sha256']==binary_sha
        assert (j['way'],j['cost'])==(x['way'],x['cost'])
        provenance.append({'report':x['file'],'sha256':x['sha256'],'job':str((p.parent/'JOB.json').relative_to(R)),'binary_sha256':binary_sha})
    write(R/'RUN_MANIFEST.json',provenance)
    acceptance=[]
    for pid in sorted({x['id'] for x in rows+r2}):
        group=[x for x in rows+r2 if x['id']==pid]
        if len(group)!=6:continue
        assert {(x['way'],x['cost']) for x in group}=={(w,c) for w in 'AB' for c in [1,1.5,2]}
        normal={x['way']:x for x in group if x['cost']==1}
        comparisons=[{'way':x['way'],'cost':x['cost'],'symbol':sym,'frozen_pnl':frozen[(x['way'],x['cost'],sym)],'pnl':x['symbols'][sym]['pnl'],'delta':x['symbols'][sym]['pnl']-frozen[(x['way'],x['cost'],sym)]} for x in group for sym in ['XAUUSD','EURUSD','BTCUSD']]
        checks={'six_scenarios':True,'audits':all(x['pass'] for x in group),'normal_A_improves':normal['A']['balance']>988747417.2738367,'normal_B_improves':normal['B']['balance']>938466200.2239354,'dd_ceiling':max(x['dd'] for x in group)<=72.21320348415222,'cost2_floor':min(x['balance'] for x in group if x['cost']==2)>=842853657.6189626}
        assets=all(x['delta']>0 for x in comparisons if x['symbol'] in ['EURUSD','BTCUSD'])
        normalassets=all(x['delta']>0 for x in comparisons if x['cost']==1 and x['symbol'] in ['EURUSD','BTCUSD'])
        acceptance.append({'id':pid,'checks':checks,'portfolio_pass':all(checks.values()),'normal_assets_improve':normalassets,'all_six_assets_improve':assets,'strict_pass':all(checks.values()) and assets,'normal_A':normal['A']['balance'],'normal_B':normal['B']['balance'],'normal_min':min(x['balance'] for x in normal.values()),'worst_dd':max(x['dd'] for x in group),'cost2_min':min(x['balance'] for x in group if x['cost']==2),'goal_both_normal_1bn':all(x['balance']>=1e9 for x in normal.values()),'pnl_comparison':comparisons})
    r2_reference=next(x for x in acceptance if x['id']=='BUFFER_EUR_BTC_V2_CANDIDATE')
    for x in acceptance:
        x['delta_vs_frozen_R2']={k:x[k]-r2_reference[k] for k in ['normal_A','normal_B','normal_min','worst_dd','cost2_min']}
    eligible=[x for x in acceptance if x['portfolio_pass']]
    assert eligible
    high=max(eligible,key=lambda x:x['normal_min']);low=min(eligible,key=lambda x:x['worst_dd'])
    pareto=[x['id'] for x in eligible if not any(y['normal_min']>=x['normal_min'] and y['worst_dd']<=x['worst_dd'] and (y['normal_min']>x['normal_min'] or y['worst_dd']<x['worst_dd']) for y in eligible)]
    write(R/'ACCEPTANCE.json',{'candidates':acceptance,'highest_conservative_normal_balance':high['id'],'lowest_all6_dd':low['id'],'pareto':pareto,'ranking_scope':'Completed full-six audited candidates only, subject to unchanged portfolio acceptance. Strict own-asset improvement remains separately required for promotion. No promotion authorized.','own_pnl_scope':prior['own_pnl_scope'],'frozen_R2_reference':frozen_r2,'frozen_unchanged':True,'live_changes':False})
    flat=[];symbols=[];timing=[];components=[];drawdowns=[]
    for x in rows:
        flat.append({k:x[k] for k in ['id','way','cost','balance','dd','pf','winrate_pct','baskets','orders','pass']})
        for sym,a in x['symbols'].items():symbols.append({'id':x['id'],'way':x['way'],'cost':x['cost'],'symbol':sym,**a})
        timing.append({'id':x['id'],'way':x['way'],'cost':x['cost'],'initial_max_seconds':x['initial_fill_max_seconds'],'btc_child_max_seconds':x['btc_latest_child_seconds'],'max_risk_pct':x['summary']['MaxObservedOpenRiskPct'],'max_margin_pct':x['summary']['MaxObservedMarginPct']})
        with gzip.open(R/x['file'],'rt') as f:d=json.load(f)
        point=max(d['Curve'],key=lambda a:a['DD'])
        drawdowns.append({'id':x['id'],'way':x['way'],'cost':x['cost'],'max_dd_pct':x['dd'],'curve_max_dd_pct':point['DD'],'at_utc':point['At'],'equity':point['Equity'],'peak':point['Peak'],'curve_matches_summary':abs(point['DD']-x['dd'])<1e-8})
        sums=collections.defaultdict(lambda:collections.defaultdict(float))
        for t in d['BrokerHistory']:
            a=sums[t['SymbolName']];a['orders']+=1
            for k in ['GrossProfit','Commissions','ExitCommission','Swap','NetProfit']:a[k]+=t[k]
        for sym,a in sums.items():components.append({'id':x['id'],'way':x['way'],'cost':x['cost'],'symbol':sym,**dict(a)})
    csvout('SCENARIOS.csv',flat);csvout('SYMBOLS.csv',symbols);csvout('TIMING_RISK.csv',timing);csvout('COST_COMPONENTS.csv',components);csvout('MAX_DD.csv',drawdowns)
    aggregates=read(R/'AGGREGATED_HISTORY.json');annual=[];monthly=[]
    for x in aggregates:
        prefix={k:x[k] for k in ['id','way','cost']}
        for v in x['annual']:annual.append({**prefix,**v})
        for v in x['cash_monthly']:monthly.append({**prefix,**v})
    csvout('ANNUAL.csv',annual);csvout('CASH_MONTHLY.csv',monthly)
    lines=['# RIZAN R3 — hasil pencarian EUR','',f"Selesai: {len(rows)} replay R3, {len(acceptance)-1} kandidat R3 dengan validasi enam skenario. Tiga konfigurasi baru; R2 digunakan kembali sebagai pembanding, tidak dihitung sebagai run baru.",'','Modal $100, tanpa top-up, compounding satu wallet. Periode 2019-01-01 sampai 2026-10-09T21:59Z. XAU dan BTC32 tetap. BUFFER V1 tidak diubah; tidak ada perubahan LIVE.','','## Kandidat lengkap','', '|Kandidat|Saldo normal A USD|Saldo normal B USD|Worst DD enam %|Minimum saldo 2× USD|Portfolio lulus|EUR/BTC seluruh enam membaik|','|---|---:|---:|---:|---:|---|---|']
    for x in acceptance:lines.append(f"|{x['id']}|{x['normal_A']:,.2f}|{x['normal_B']:,.2f}|{x['worst_dd']:.6f}|{x['cost2_min']:,.2f}|{x['portfolio_pass']}|{x['all_six_assets_improve']}|")
    lines+=['',f"Saldo normal terendah lintas A/B terbesar: **{high['id']}**. Worst DD enam skenario terendah: **{low['id']}**. Pemilihan ini terbatas pada kandidat lengkap yang memenuhi batas portfolio lama; bukan bukti optimum global.",'','## Semua run R3','', '|ID|Jalur|Biaya|Saldo USD|DD %|PF|Winrate basket %|Basket|Opening order|Audit|','|---|---|---:|---:|---:|---:|---:|---:|---:|---|']
    for x in flat:lines.append(f"|{x['id']}|{x['way']}|{x['cost']}|{x['balance']:,.2f}|{x['dd']:.6f}|{x['pf']:.6f}|{x['winrate_pct']:.4f}|{x['baskets']}|{x['orders']}|{x['pass']}|")
    lines+=['','## Kontribusi dan audit','','SYMBOLS.csv memisahkan PnL XAU/EUR/BTC, PF dan winrate basket. CASH_MONTHLY.csv berisi PnL berdasarkan bulan kas; AGGREGATED_HISTORY.json juga menyimpan PnL basket berdasarkan bulan entry. ANNUAL.csv menyimpan 2019–2026 parsial. COST_COMPONENTS.csv memisahkan gross, komisi dan funding. TIMING_RISK.csv menyimpan delay firstfill/child dan maksimum rasio risiko/margin.','','Audit memeriksa kas dan ledger, no top-up, flat, no errors/quarantine/accounting block/forced close, equity positif, cutoff, seluruh order tercatat, komponen biaya, cap volume per order, XAU lock, status terminal BTC dan deadline fill. Tidak ada perubahan kode; DLL yang digunakan identik dengan R2 dengan bukti 1.247 tes lama + 474 tes batch dalam arsip acuan.','','Batas portfolio tetap: normal A >988747417.2738367; normal B >938466200.2239354; worst DD ≤72.21320348415222%; minimum saldo A/B biaya2× ≥842853657.6189626. Syarat konservatif peningkatan PnL EUR dan BTC di seluruh enam tetap dilaporkan terpisah. Semua kegagalan tercantum di ACCEPTANCE.json. Tidak ada promosi kandidat.','','## Batas kesimpulan','','Replay M1 memakai jalur OHLC sintetis A/B dan delay broker 2 detik. Stress biaya mengubah komisi, slippage dan funding; spread tetap. Cap risiko20,75%/margin50% berlaku saat sizing; rasio teramati bisa melampaui setelah harga bergerak. Belum native tick, OOS independen, vintage makro, likuiditas/market impact dan margin broker nyata; saldo bukan hasil LIVE.']
    (R/'REPORT.md').write_text('\n'.join(lines)+'\n')
    (R/'PROGRESS.md').write_text('Putaran R3 selesai. Baca REPORT.md, ACCEPTANCE.json dan FINAL_STATUS.json untuk hasil akhir. Snapshot sementara sebelumnya telah digantikan oleh laporan lengkap.\n')
    (R/'README.md').write_text('RIZAN R3 completed research checkpoint, 28 October 2026.\n\nRead REPORT.md and ACCEPTANCE.json first. All results are historical synthetic replay, not LIVE. BUFFER V1 and XAU/BTC32 parameters remain unchanged. SHA256.json in the archive verifies members.\n\nThis package contains R3 configs, raw reports, audits, cash annual/monthly data, costs, timing/risk, drawdown dates, code and DLL. The prior complete R2 archive and original data provenance remain at Library libfile_583f19ae940c8191a192731d6e8c7274 (SHA256 e60974fafbb9e7d47f6dea27e0bc5e1e56d6433d1601f4c467a8b2cf587fe4ae). Restore that archive to r3_restore/r2 and the original FX input package/runtime to the documented workspace paths before replaying. Original FX/BTC SHA256 values are in INPUTS.json.\n\nThe packed state precedes the final upload receipt. A complete replay status is distinct from proof that a worker remains running after interruption. Do not rerun finish_and_save.py blindly on a newer Library version; its replacement guard is version0.\n')
    write(R/'FINAL_STATUS.json',{'complete':True,'at_utc':time.time(),'r3_runs':len(rows),'new_configs':3,'full6_r3_candidates':len(acceptance)-1,'high_balance':high['id'],'low_dd':low['id'],'pareto':pareto,'live_changes':False,'frozen_unchanged':True})
    print(json.dumps(read(R/'FINAL_STATUS.json'),indent=2))

if __name__=='__main__':main()

