from pathlib import Path
import time,json,subprocess,sys,zipfile,hashlib

R=Path(__file__).resolve().parent
WS=R.parent
def main():
    while True:
        status=json.loads((R/'STATUS.json').read_text())
        if status.get('complete'):break
        if status.get('stage')=='error':raise RuntimeError(status)
        time.sleep(15)
    subprocess.run([sys.executable,str(R/'finalize_r3.py')],check=True)
    payload={}
    for p in sorted(R.rglob('*')):
        if p.is_file() and not p.is_symlink() and '__pycache__' not in p.parts and p.name not in ['SAVE_RECEIPT.json','finish.log'] and not p.name.endswith('.tmp'):
            payload['r3_research/'+str(p.relative_to(R))]=p.read_bytes()
    base=WS/'r3_restore/r2/buffer_growth'
    for p in sorted((base/'work_r2').rglob('*')):
        if p.is_file():payload['r2_code/work_r2/'+str(p.relative_to(base/'work_r2'))]=p.read_bytes()
    for name in ['RESULTS.json','COMBINED_ACCEPTANCE.json','CONTROL_PARITY_R2_FULL.json','REBUILT_UNIT_TESTS.json','BATCH_TEST_RESULTS.json']:
        p=base/name
        if p.is_file():payload['r2_reference/'+name]=p.read_bytes()
    manifest={k:hashlib.sha256(v).hexdigest() for k,v in payload.items()}
    payload['SHA256.json']=json.dumps(manifest,indent=2).encode()
    out=WS/'RIZAN_R3_RESEARCH_20261028.zip';tmp=out.with_suffix('.tmp')
    with zipfile.ZipFile(tmp,'w',zipfile.ZIP_DEFLATED) as z:
        for name,content in payload.items():
            z.writestr(name,content,compress_type=zipfile.ZIP_STORED if name.endswith('.gz') else zipfile.ZIP_DEFLATED)
    tmp.replace(out)
    with zipfile.ZipFile(out) as z:
        assert len(z.namelist())==len(set(z.namelist()))
        assert all(hashlib.sha256(z.read(k)).hexdigest()==v for k,v in manifest.items())
    summary={'path':str(out),'bytes':out.stat().st_size,'sha256':hashlib.file_digest(out.open('rb'),'sha256').hexdigest(),'manifest_entries':len(manifest)}
    (R/'PACK.json').write_text(json.dumps(summary,indent=2));print('PACKED',json.dumps(summary),flush=True)
    print('Saving completed R3 results',flush=True)
    request={'uploads':[{'local_path':str(out),'purpose':'replace_library_file','library_file_id':'libfile_2debd92450a88191901de3687568103a','expected_current_version':0,'version_reason':'Completed R3 replay results, full audits, source, configs and report'}]}
    result=subprocess.run([sys.executable,str(WS/'.transfer_r3/library_upload.py')],input=json.dumps(request),text=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    (R/'SAVE_RECEIPT.json').write_text(result.stdout);(R/'SAVE_ERROR.log').write_text(result.stderr)
    print('SAVE_EXIT',result.returncode,flush=True)
